# -*- coding: utf-8 -*-
# =============================================================================
# NETTRADES Good Answer - Dataset Contribution model
# =============================================================================
# Records which professionals contributed expert answers to a fine-tuning
# dataset.  Used later to award indirect reputation points when an AI
# answer (generated by a model trained on this dataset) receives a
# Good Answer vote.
# =============================================================================
from odoo import fields, models


class FTDatasetContribution(models.Model):
    _name = 'ft.dataset.contribution'
    _description = 'Professional Contribution to Fine-Tuning Dataset'

    dataset_id = fields.Many2one(
        'ft.dataset', required=True, ondelete='cascade',
        help="The fine-tuning dataset this professional contributed to."
    )
    partner_id = fields.Many2one(
        'res.partner', string='Professional', required=True,
        help="The professional whose expert answer was used."
    )
    points_contributed = fields.Integer(
        default=1,
        help="Weight of this professional's contribution "
             "(higher = more influence on the model)."
    )
    created_at = fields.Datetime(default=fields.Datetime.now)